(2407521, 329801, 55746, '<td valign="top">What a sweet face!</td>', 'What a sweet face!', '2006-05-11 21:41:33.000000', NULL, 1),
(2407526, 332204, 55746, '<td valign="top">Nice capture!</td>', 'Nice capture!', '2006-05-11 21:43:45.000000', NULL, 1),
(2407529, 331870, 55746, '<td valign="top">Very nice choice of subject.  I love the texture.</td>', 'Very nice choice of subject.  I love the texture.', '2006-05-11 21:44:42.000000', NULL, 1),
(2407539, 332110, 55746, '<td valign="top">Gorgeous!  Wonderful choice of subject.  Colors pop.  I would like to live there!</td>', 'Gorgeous!  Wonderful choice of subject.  Colors pop.  I would like to live there!', '2006-05-11 21:50:03.000000', NULL, 1),
