(2410901, 331704, 33672, '<td valign="top">Crisp and clear. Nice use of negative space. Great colors.</td>', 'Crisp and clear. Nice use of negative space. Great colors.', '2006-05-12 22:47:42.000000', NULL, 1),
(2410908, 329635, 33672, '<td valign="top">Man I love NYC! Nice perspective and comp.  It just seems that it may have been the wrong time of day to take this as the sun and shadows detract from the photo IMO.</td>', 'Man I love NYC! Nice perspective and comp.  It just seems that it may have been the wrong time of day to take this as the sun and shadows detract from the photo IMO.', '2006-05-12 22:49:12.000000', NULL, 1),
