(2414531, 330320, 52114, '<td valign="top">The composition is great, but the image is too blurry.</td>', 'The composition is great, but the image is too blurry.', '2006-05-14 14:23:38.000000', NULL, 1),
(2414532, 331857, 52114, '<td valign="top">The angle captures every aspect of this churches beauty.</td>', 'The angle captures every aspect of this churches beauty.', '2006-05-14 14:24:22.000000', NULL, 1),
(2414534, 331138, 52114, '<td valign="top">Really like the color on the horizon.</td>', 'Really like the color on the horizon.', '2006-05-14 14:24:47.000000', NULL, 1),
(2414535, 331972, 52114, '<td valign="top">Creates a nice shadow of the croos on the grass, maybe too light.</td>', 'Creates a nice shadow of the croos on the grass, maybe too light.', '2006-05-14 14:26:07.000000', NULL, 1),
(2414539, 329954, 52114, '<td valign="top">Its fantastic and i would love to know how you were able to capture this image. The colors are the best parts.</td>', 'Its fantastic and i would love to know how you were able to capture this image. The colors are the best parts.', '2006-05-14 14:28:08.000000', NULL, 1),
(2414543, 332062, 52114, '<td valign="top">The idea is cool because it forces the viewer to look through the old and see whats preserved. Nice use of composition.</td>', 'The idea is cool because it forces the viewer to look through the old and see whats preserved. Nice use of composition.', '2006-05-14 14:29:17.000000', NULL, 1),
(2414544, 330584, 52114, '<td valign="top">NIce concept, although lighting is just a little harsh on the front of the church.</td>', 'NIce concept, although lighting is just a little harsh on the front of the church.', '2006-05-14 14:29:56.000000', NULL, 1),
(2414547, 332449, 52114, '<td valign="top">Nice ideas, but the image is very grainy maybe a different resolution could solve this issue.</td>', 'Nice ideas, but the image is very grainy maybe a different resolution could solve this issue.', '2006-05-14 14:30:49.000000', NULL, 1),
(2414548, 330417, 52114, '<td valign="top">All I can say is WOW, Its is fantastic and the colors comined in their values id stunning.</td>', 'All I can say is WOW, Its is fantastic and the colors comined in their values id stunning.', '2006-05-14 14:31:43.000000', NULL, 1),
(2414553, 332190, 52114, '<td valign="top">The image is really interesting, although it seems as if the building was photoshopped into the image.</td>', 'The image is really interesting, although it seems as if the building was photoshopped into the image.', '2006-05-14 14:33:00.000000', NULL, 1),
(2414558, 331038, 52114, '<td valign="top">The colors are outstanding and pull this image together really creating a one of a kind piece.</td>', 'The colors are outstanding and pull this image together really creating a one of a kind piece.', '2006-05-14 14:36:27.000000', NULL, 1),
(2414560, 330166, 52114, '<td valign="top">Great image, colors and values are awesome, it would make a great poster.</td>', 'Great image, colors and values are awesome, it would make a great poster.', '2006-05-14 14:40:57.000000', NULL, 1),
(2414562, 331186, 52114, '<td valign="top">The angle up draws ones attention and the blue really stands out.</td>', 'The angle up draws ones attention and the blue really stands out.', '2006-05-14 14:42:44.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2414564, 329777, 52114, '<td valign="top">Nice image but how is this a holy place? NIce use of value.</td>', 'Nice image but how is this a holy place? NIce use of value.', '2006-05-14 14:43:21.000000', NULL, 1),
(2414570, 331997, 52114, '<td valign="top">The image is a little boring and doesn''t really jump out at you.</td>', 'The image is a little boring and doesn''t really jump out at you.', '2006-05-14 14:48:03.000000', NULL, 1),
(2414573, 332342, 52114, '<td valign="top">Absolutely love it the way christ seems to be watching over the little boy.</td>', 'Absolutely love it the way christ seems to be watching over the little boy.', '2006-05-14 14:49:39.000000', NULL, 1),
(2414576, 330169, 52114, '<td valign="top">The little statue is creating a peaceful feel</td>', 'The little statue is creating a peaceful feel', '2006-05-14 14:50:17.000000', NULL, 1),
(2414606, 332275, 48315, '<td valign="top">good concept</td>', 'good concept', '2006-05-14 15:11:13.000000', NULL, 1),
(2414611, 331177, 48315, '<td valign="top">Good composition</td>', 'Good composition', '2006-05-14 15:14:10.000000', NULL, 1),
(2414613, 331606, 48315, '<td valign="top">I like the concept</td>', 'I like the concept', '2006-05-14 15:16:04.000000', NULL, 1),
(2414614, 332454, 48315, '<td valign="top">I like the concept</td>', 'I like the concept', '2006-05-14 15:16:40.000000', NULL, 1),
(2414624, 331961, 40370, '<td valign="top">I like the concept of the two tall lines, needs a little color saturation and sharpening though, or maybe converted to black &amp; white.</td>', 'I like the concept of the two tall lines, needs a little color saturation and sharpening though, or maybe converted to black & white.', '2006-05-14 15:26:29.000000', NULL, 1),
(2414627, 329510, 40370, '<td valign="top">Beautiful path under a ceiling of blossoms but unfortunately the image appears over-done in editing.</td>', 'Beautiful path under a ceiling of blossoms but unfortunately the image appears over-done in editing.', '2006-05-14 15:28:23.000000', NULL, 1),
(2414628, 331820, 40370, '<td valign="top">Beautiful ornate statue, looks like you may have desaturated color, I wonder what this would look like with a pop of color to enhance the decorations on the figure. Could benefit from a little sharpening as well.</td>', 'Beautiful ornate statue, looks like you may have desaturated color, I wonder what this would look like with a pop of color to enhance the decorations on the figure. Could benefit from a little sharpening as well.', '2006-05-14 15:31:00.000000', NULL, 1),
(2414632, 330423, 40370, '<td valign="top">Needs a little straightening in post processing, maybe a bump up in the blue channel, otherwise the shine on the cross fits this challenge nicely.</td>', 'Needs a little straightening in post processing, maybe a bump up in the blue channel, otherwise the shine on the cross fits this challenge nicely.', '2006-05-14 15:34:15.000000', NULL, 1),
(2414637, 332185, 40370, '<td valign="top">Wow, only if priests(and all other religious leaders) could get attendence this high. Quick pass the donation plate.</td>', 'Wow, only if priests(and all other religious leaders) could get attendence this high. Quick pass the donation plate.', '2006-05-14 15:36:23.000000', NULL, 1),
(2414642, 331038, 40370, '<td valign="top">Love the unique figurine and the wonderful colors just POP!!</td>', 'Love the unique figurine and the wonderful colors just POP!!', '2006-05-14 15:39:28.000000', NULL, 1),
(2414645, 330740, 40370, '<td valign="top">The dark rich colors are wonderful, interesting POV, my gaze slowly makes its way to the bright star burst enjoying all the detail on the journey.</td>', 'The dark rich colors are wonderful, interesting POV, my gaze slowly makes its way to the bright star burst enjoying all the detail on the journey.', '2006-05-14 15:41:48.000000', NULL, 1),
(2414654, 332159, 40370, '<td valign="top">Great composition, the detailed red lines are exceptional. I may have bumped up the whites just a bit in selective color, only if the adjustment left the beautiful detail in the other colors.</td>', 'Great composition, the detailed red lines are exceptional. I may have bumped up the whites just a bit in selective color, only if the adjustment left the beautiful detail in the other colors.', '2006-05-14 15:45:51.000000', NULL, 1),
(2414662, 332456, 40370, '<td valign="top">Humble ... great DOF and Comp. with the cross in the background, a fine portrait of a beautiful woman. Thanks for sharing this image.</td>', 'Humble ... great DOF and Comp. with the cross in the background, a fine portrait of a beautiful woman. Thanks for sharing this image.', '2006-05-14 15:49:31.000000', NULL, 1),
(2414746, 330794, 43115, '<td valign="top">There is an unsettling blue cast to this entire image.  :(</td>', 'There is an unsettling blue cast to this entire image.  :(', '2006-05-14 16:49:03.000000', NULL, 1),
(2414747, 331508, 43115, '<td valign="top">Very pretty, but the trees in the foreground distract from the buiding behind.</td>', 'Very pretty, but the trees in the foreground distract from the buiding behind.', '2006-05-14 16:49:29.000000', NULL, 1),
(2414749, 331820, 43115, '<td valign="top">There''s something odd about the color (or lack of it) in this shot.  It looks partially desaturated, but then why not go black and white?</td>', 'There''s something odd about the color (or lack of it) in this shot.  It looks partially desaturated, but then why not go black and white?', '2006-05-14 16:50:12.000000', NULL, 1),
(2414750, 329971, 43115, '<td valign="top">Nicely done, and a good choice for conversion to B&amp;W.</td>', 'Nicely done, and a good choice for conversion to B&W.', '2006-05-14 16:50:41.000000', NULL, 1),
(2414753, 330804, 43115, '<td valign="top">Nice sky, but not a horribly compelling image.  The people don''t do anything for the photo since they''re just ...there...  Also, you''re off center from the front of the church... see the difference in the bricks alongside the stairs on the right vs. the left?</td>', 'Nice sky, but not a horribly compelling image.  The people don''t do anything for the photo since they''re just ...there...  Also, you''re off center from the front of the church... see the difference in the bricks alongside the stairs on the right vs. the left?', '2006-05-14 16:52:18.000000', NULL, 1),
(2414755, 331389, 43115, '<td valign="top">Very nicely done.  I think a little less DOF would have isolated the stone in the foreground also very effectivley.</td>', 'Very nicely done.  I think a little less DOF would have isolated the stone in the foreground also very effectivley.', '2006-05-14 16:53:16.000000', NULL, 1),
(2414756, 331516, 43115, '<td valign="top">Nice, but flat lighting.</td>', 'Nice, but flat lighting.', '2006-05-14 16:53:31.000000', NULL, 1),
(2414757, 332400, 43115, '<td valign="top">This photo is very well done, but it relies on the title to make the link to "holy places."  A photo that speaks for itself will always score better than one that requires the title to link it into the challenge.  This is quite pretty, but not very strong link to the challenge.</td>', 'This photo is very well done, but it relies on the title to make the link to "holy places."  A photo that speaks for itself will always score better than one that requires the title to link it into the challenge.  This is quite pretty, but not very strong link to the challenge.', '2006-05-14 16:54:50.000000', NULL, 1),
(2414759, 331870, 43115, '<td valign="top">Nicely done, but perhaps just a smidge over-sharpened.  The statue in the foreground seems to have some "glowing" around the edges between the dark areas and the light areas.  I like the use of DOF to fuzzy up the tombstones in the background.</td>', 'Nicely done, but perhaps just a smidge over-sharpened.  The statue in the foreground seems to have some "glowing" around the edges between the dark areas and the light areas.  I like the use of DOF to fuzzy up the tombstones in the background.', '2006-05-14 16:56:40.000000', NULL, 1),
(2414760, 331750, 43115, '<td valign="top">Nicely done, but the lighting seems a little artificial.</td>', 'Nicely done, but the lighting seems a little artificial.', '2006-05-14 16:57:04.000000', NULL, 1),
(2414765, 331606, 43115, '<td valign="top">Good choice for conversion to black and white.  I would have either lit the statues in the foreground a little more so that you could make out the details in them, or moved forward to exclude them from the photo.  As it is composed now they''re a little distracting.</td>', 'Good choice for conversion to black and white.  I would have either lit the statues in the foreground a little more so that you could make out the details in them, or moved forward to exclude them from the photo.  As it is composed now they''re a little distracting.', '2006-05-14 16:59:33.000000', NULL, 1),
(2414783, 331520, 43115, '<td valign="top">I think this might have worked a little better if it was taken from a lower angle... to be more on the level of the girls.</td>', 'I think this might have worked a little better if it was taken from a lower angle... to be more on the level of the girls.', '2006-05-14 17:14:31.000000', NULL, 1),
(2414787, 331670, 43115, '<td valign="top">Here''s what kills this photo for me... The big half motion/half ghost guy in the foreground.  I get the motion blur of the rest of the people in the photo, but the focal point of the photo should be the wall and the people drawn there.  Every time I try to look at that, I get distracted by this giant ghostly face in the foreground.  :(  Nice lighting on the wall and otherwise really well done.</td>', 'Here''s what kills this photo for me... The big half motion/half ghost guy in the foreground.  I get the motion blur of the rest of the people in the photo, but the focal point of the photo should be the wall and the people drawn there.  Every time I try to look at that, I get distracted by this giant ghostly face in the foreground.  :(  Nice lighting on the wall and otherwise really well done.', '2006-05-14 17:16:24.000000', NULL, 1),
(2414788, 332461, 43115, '<td valign="top">I would like to see this using the full 640 pixels.  I think the detail in the sculptures is lost and looks really jagged.  A bigger canvas (even if it was just a little bigger) would have helped that, I think.  I really like the silhouette, and the sky is <i>very</i> dramatic.</td>', 'I would like to see this using the full 640 pixels.  I think the detail in the sculptures is lost and looks really jagged.  A bigger canvas (even if it was just a little bigger) would have helped that, I think.  I really like the silhouette, and the sky is very dramatic.', '2006-05-14 17:16:34.000000', NULL, 1),
(2414795, 330800, 43115, '<td valign="top">The biggest problem I have with this photo is that is seems to lean to the bottom right.  Perhaps a simple rotation counter-clockwise in photoshop to straighten things up would have helped a bit.</td>', 'The biggest problem I have with this photo is that is seems to lean to the bottom right.  Perhaps a simple rotation counter-clockwise in photoshop to straighten things up would have helped a bit.', '2006-05-14 17:18:21.000000', NULL, 1),
(2414798, 330613, 43115, '<td valign="top">A decent shot, a pretty scene.  But I a shot that only links to the challenge through the title isn''t as strong as one which speaks for itself.</td>', 'A decent shot, a pretty scene.  But I a shot that only links to the challenge through the title isn''t as strong as one which speaks for itself.', '2006-05-14 17:19:29.000000', NULL, 1),
(2414802, 331138, 55767, '<td valign="top">nice silhouette and I love the color of the rising sun.</td>', 'nice silhouette and I love the color of the rising sun.', '2006-05-14 17:20:56.000000', NULL, 1),
(2414803, 330915, 43115, '<td valign="top">This looks just a little <i>too</i> juiced in post processing.  :(</td>', 'This looks just a little too juiced in post processing.  :(', '2006-05-14 17:20:59.000000', NULL, 1),
(2414811, 331361, 55767, '<td valign="top">a very moving photo.</td>', 'a very moving photo.', '2006-05-14 17:24:50.000000', NULL, 1),
(2414819, 332287, 55767, '<td valign="top">I like this. I find it very serene.</td>', 'I like this. I find it very serene.', '2006-05-14 17:28:55.000000', NULL, 1),
(2414822, 331178, 43115, '<td valign="top">Very powerful.  This photo <i>tells</i> a story.<br/>Edit: Bumped to 10 for the sheer emotion present in this photo.  National Geographic quality stuff.</td>', 'Very powerful.  This photo tells a story.Edit: Bumped to 10 for the sheer emotion present in this photo.  National Geographic quality stuff.', '2006-05-14 17:29:59.000000', NULL, 1),
(2414823, 332202, 43115, '<td valign="top">A great choice for conversion to B&amp;W.  Excellent shot.</td>', 'A great choice for conversion to B&W.  Excellent shot.', '2006-05-14 17:31:07.000000', NULL, 1),
(2414824, 330464, 43115, '<td valign="top">The vibrant colors really make this photo.  Great capture!</td>', 'The vibrant colors really make this photo.  Great capture!', '2006-05-14 17:31:19.000000', NULL, 1),
(2414825, 332217, 43115, '<td valign="top">I do quite like the post processing that you used to "fuzzy" this photo.  It''s a great scene and well captured.</td>', 'I do quite like the post processing that you used to "fuzzy" this photo.  It''s a great scene and well captured.', '2006-05-14 17:31:36.000000', NULL, 1),
(2414827, 330440, 43115, '<td valign="top">The yellow and blue are very powerful contrasts to each other.  Great shot, really pops off at the viewer.</td>', 'The yellow and blue are very powerful contrasts to each other.  Great shot, really pops off at the viewer.', '2006-05-14 17:32:03.000000', NULL, 1),
(2414829, 331186, 43115, '<td valign="top">Amazing that you were able to capture all that detail without introducting jagged edges, jpeg compression problems, or any of the other technical problems  these types of photos usually encounter.</td>', 'Amazing that you were able to capture all that detail without introducting jagged edges, jpeg compression problems, or any of the other technical problems  these types of photos usually encounter.', '2006-05-14 17:33:12.000000', NULL, 1),
(2414830, 330169, 43115, '<td valign="top">Very well done!  The depth of field you chose is great and I really like the composition.  Tack sharp, an interesting scene... great capture.</td>', 'Very well done!  The depth of field you chose is great and I really like the composition.  Tack sharp, an interesting scene... great capture.', '2006-05-14 17:33:27.000000', NULL, 1),
(2414832, 330417, 43115, '<td valign="top">Another Islandic ribbon, I''d wager... :)</td>', 'Another Islandic ribbon, I''d wager... :)', '2006-05-14 17:34:14.000000', NULL, 1),
(2414984, 332478, 44878, '<td valign="top">I hope you win this Challenge, and I am in it !<br/>Its superb, Well Done</td>', 'I hope you win this Challenge, and I am in it !Its superb, Well Done', '2006-05-14 19:03:22.000000', NULL, 1),
(2415059, 332199, 52713, '<td valign="top">been there!</td>', 'been there!', '2006-05-14 19:33:31.000000', NULL, 1),
