(2415402, 330915, 30982, '<td valign="top">Nicely seen - the silhouette and the sun shining through work well together.</td>', 'Nicely seen - the silhouette and the sun shining through work well together.', '2006-05-14 22:36:35.000000', NULL, 1),
(2415406, 331259, 30982, '<td valign="top">Simple and elegant.</td>', 'Simple and elegant.', '2006-05-14 22:41:57.000000', NULL, 1),
