(2415413, 332460, 30982, '<td valign="top">Very nice capture of the light!</td>', 'Very nice capture of the light!', '2006-05-14 22:50:27.000000', NULL, 1),
(2415414, 330794, 30982, '<td valign="top">The sky is a bit of an odd shade.</td>', 'The sky is a bit of an odd shade.', '2006-05-14 22:53:03.000000', NULL, 1),
(2415416, 331954, 30982, '<td valign="top">Very nice symmetry!</td>', 'Very nice symmetry!', '2006-05-14 22:53:30.000000', NULL, 1),
(2415419, 331031, 30982, '<td valign="top">Very nice choice of perspective - well executed.</td>', 'Very nice choice of perspective - well executed.', '2006-05-14 22:56:38.000000', NULL, 1),
(2415423, 330063, 34134, '<td valign="top">Interesting angle.</td>', 'Interesting angle.', '2006-05-14 22:59:58.000000', NULL, 1),
