(2415473, 332351, 30982, '<td valign="top">The border here overpowers the picture a bit.</td>', 'The border here overpowers the picture a bit.', '2006-05-14 23:24:09.000000', NULL, 1),
(2415480, 329777, 39363, '<td valign="top">I don''t understand what is holy about this?</td>', 'I don''t understand what is holy about this?', '2006-05-14 23:26:31.000000', NULL, 1),
(2415481, 332483, 37730, '<td valign="top">A very interesting take on this.  Nicely done.</td>', 'A very interesting take on this.  Nicely done.', '2006-05-14 23:26:34.000000', NULL, 1),
(2415486, 332229, 30982, '<td valign="top">Good composition with the leading lines of the trees.  Appears oversharpened to me, though.</td>', 'Good composition with the leading lines of the trees.  Appears oversharpened to me, though.', '2006-05-14 23:29:50.000000', NULL, 1),
