INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(2417965, 332446, 57714, '<td valign="top">Simply beautiful</td>', 'Simply beautiful', '2006-05-15 15:57:36.000000', NULL, 1),
(2417968, 332314, 58827, '<td valign="top">Nice. Would have given it a 10 if there wasn''t banding in the sky. Wonderful photo.</td>', 'Nice. Would have given it a 10 if there wasn''t banding in the sky. Wonderful photo.', '2006-05-15 15:58:12.000000', NULL, 1),
(2417973, 331660, 57714, '<td valign="top">not a fan of the yellow sky... other than that; nice, simple, clean</td>', 'not a fan of the yellow sky... other than that; nice, simple, clean', '2006-05-15 15:58:59.000000', NULL, 1),
(2417976, 331770, 58827, '<td valign="top">Beautiful lighting.</td>', 'Beautiful lighting.', '2006-05-15 15:59:46.000000', NULL, 1),
(2417981, 332202, 39349, '<td valign="top">Love your choice of duotone in this shot. It really makes it feel old world as if I''m stepping back in time. Wonderful focus and I like the dark to light you have working for you left to right frame. Well done 10 from me.</td>', 'Love your choice of duotone in this shot. It really makes it feel old world as if I''m stepping back in time. Wonderful focus and I like the dark to light you have working for you left to right frame. Well done 10 from me.', '2006-05-15 16:03:09.000000', NULL, 1),
(2417985, 329685, 39349, '<td valign="top">Another amazing shot for me to vote on. I love your choice of perspective here showing off such amazing architecture, little distraction in the upper left but still a wonderful shot that you should be very proud of.</td>', 'Another amazing shot for me to vote on. I love your choice of perspective here showing off such amazing architecture, little distraction in the upper left but still a wonderful shot that you should be very proud of.', '2006-05-15 16:04:23.000000', NULL, 1),
(2417991, 330417, 39349, '<td valign="top">One of my pics for the top spot in this challenge. I''m just amazed at the symbolism of this shot. The darkness all around and the beacon of light protruding out of the darkness. The reflection of the church really makes this a powerful image that stands out from many of the entries. Wonderful, 10 from me.</td>', 'One of my pics for the top spot in this challenge. I''m just amazed at the symbolism of this shot. The darkness all around and the beacon of light protruding out of the darkness. The reflection of the church really makes this a powerful image that stands out from many of the entries. Wonderful, 10 from me.', '2006-05-15 16:07:00.000000', NULL, 1),
(2418000, 331669, 39349, '<td valign="top">Simply put, amazing, I''m fortunate to have experienced this wonderful place. First off, I love the playing with light throughout this shot. Shadows are playing nicely for you here without loss of detail; the clouds are dramatic and create an old west feeling that takes me back in time. Tones are perfect IMHO, focus in spot on and composition is perfection. WELL DONE!</td>', 'Simply put, amazing, I''m fortunate to have experienced this wonderful place. First off, I love the playing with light throughout this shot. Shadows are playing nicely for you here without loss of detail; the clouds are dramatic and create an old west feeling that takes me back in time. Tones are perfect IMHO, focus in spot on and composition is perfection. WELL DONE!', '2006-05-15 16:15:03.000000', NULL, 1),
(2418004, 331560, 39349, '<td valign="top">Love the composition, could perhaps use a bit more saturation but still a wonderful shot. Bumping up.</td>', 'Love the composition, could perhaps use a bit more saturation but still a wonderful shot. Bumping up.', '2006-05-15 16:16:42.000000', NULL, 1),
(2418008, 330517, 39349, '<td valign="top">Loved this show, and I could see this as an add for it. Great washed out tones really make this image have the feeling I got when watching this program. I''m also really liking your composition, and DOF. Well done, bumping up.</td>', 'Loved this show, and I could see this as an add for it. Great washed out tones really make this image have the feeling I got when watching this program. I''m also really liking your composition, and DOF. Well done, bumping up.', '2006-05-15 16:18:12.000000', NULL, 1),
(2418013, 332470, 39349, '<td valign="top">Wonderful textures working for you in this shot. I like your choice of post processing as well, gives this shot real emotion. Well done.</td>', 'Wonderful textures working for you in this shot. I like your choice of post processing as well, gives this shot real emotion. Well done.', '2006-05-15 16:18:56.000000', NULL, 1),
(2418014, 330740, 39349, '<td valign="top">Beautiful textures throughout this magnificent shot and building. Well done.</td>', 'Beautiful textures throughout this magnificent shot and building. Well done.', '2006-05-15 16:19:33.000000', NULL, 1),
(2418015, 331700, 39349, '<td valign="top">Amazing detail in this shot. Beautiful colors and composition.</td>', 'Amazing detail in this shot. Beautiful colors and composition.', '2006-05-15 16:19:38.000000', NULL, 1),
