(2424691, 331956, 40580, '<td valign="top">No place to go but up.  Good luck next time.</td>', 'No place to go but up.  Good luck next time.', '2006-05-17 10:54:30.000000', NULL, 0),
(2424716, 331711, 52336, '<td valign="top">The wonderful view of those arches make this picture great.  You''ve selected a great composition using them, and the central doorway arching up into the composition from below really gives it a great feel.  It might have been best to shoot "up" more, avoiding a lot of the ground, which is likely too flat and unintersting for this image.  It could be said that the ground is a nice contrast to the way the image is composed above.  A great photograph, congratulations.</td>', 'The wonderful view of those arches make this picture great.  You''ve selected a great composition using them, and the central doorway arching up into the composition from below really gives it a great feel.  It might have been best to shoot "up" more, avoiding a lot of the ground, which is likely too flat and unintersting for this image.  It could be said that the ground is a nice contrast to the way the image is composed above.  A great photograph, congratulations.', '2006-05-17 11:00:09.000000', NULL, 0),
(2424742, 330417, 29156, '<td valign="top">well done</td>', 'well done', '2006-05-17 11:07:32.000000', NULL, 0),
